import random
from boltons.dictutils import OrderedMultiDict, FastIterOrderedMultiDict
for seed in range(100):
    random.seed(seed)
    a, b = OrderedMultiDict(), FastIterOrderedMultiDict()
    ops=[]
    for i in range(100):
        k=random.randrange(5); v=random.randrange(10)
        op=random.choice(['add','set','pop','popall','poplast'])
        ops.append((op,k,v))
        for obj in (a,b):
            try:
                if op=='add': obj.add(k,v)
                elif op=='set': obj[k]=v
                else: getattr(obj,op)(k)
            except KeyError: pass
        for multi in (False,True):
            assert list(a.iterkeys(multi))==list(b.iterkeys(multi)), (seed,ops,'keys',multi)
            assert list(a.iteritems(multi))==list(b.iteritems(multi)), (seed,ops,'items',multi,list(a.iteritems(multi)),list(b.iteritems(multi)))
        assert list(reversed(a))==list(reversed(b)), (seed,ops,'reversed')
print('FastIterOrderedMultiDict matches OrderedMultiDict across 10000 mutations')
PY
